import pandas as pddef select_best_spectra_by_li(input_csv, output_csv="best_li_spectra.csv"):    # Load the CSV    df = pd.read_csv(input_csv)    print(f"Loaded {len(df)} spectra")    # Convert Li SNR to numeric (    df["SNR-Li"] = pd.to_numeric(df["SNR-Li"], errors="coerce")    # Remove rows where Li SNR is missing    df = df.dropna(subset=["SNR-Li"])    # Finding the index of the highest Li SNR for each target    best_indices = df.groupby("Target")["SNR-Li"].idxmax()    # Select those rows    best_spectra = df.loc[best_indices]    # Sort by target    best_spectra = best_spectra.sort_values("Target")    # Save result    best_spectra.to_csv(output_csv, index=False)    print(f"Selected {len(best_spectra)} best spectra (one per target)")    print(f"Saved to {output_csv}")# Run itselect_best_spectra_by_li("Carmen_master_spectra.csv")